(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"آج سب کچھ کرنا ضروری نہیں۔ بس اگلا چھوٹا کام کافی ہے۔\", \"تھکنا ہار جانا نہیں ہے۔ آپ تھکی ہوئی ہیں کیونکہ آپ ہر روز ڈٹی رہتی ہیں۔\", \"برتن انتظار کر سکتے ہیں۔ آپ کو پانچ منٹ بیٹھنے کا پورا حق ہے۔\", \"رات کے کھانے میں سیریل بھی گھر والوں کا پیٹ بھرنا ہی ہے۔\", \"آرام کمانا نہیں پڑتا۔ آپ ابھی اسی وقت آرام کر سکتی ہیں۔\", \"کچھ دنوں میں جیت یہی ہوتی ہے کہ سب سونے کے وقت تک خیریت سے پہنچ گئے۔ یہ سچی جیت ہے۔\", \"آپ جتنا کرتی ہیں، اتنا کوئی نہیں دیکھتا۔ میں دیکھتی ہوں۔\", \"بکھرا ہوا گھر اور پیار میں پلے بچے۔ یہ اچھا سودا ہے۔\", \"مشکل دن میں آپ کی پوری کوشش مختلف دکھتی ہے، پھر بھی وہ گنی جاتی ہے۔\", \"ایک گہری سانس۔ کندھے ڈھیلے چھوڑ دیں۔ آپ اچھا کر رہی ہیں۔\", \"آج توقعات کچھ کم رکھنا ٹھیک ہے۔ کسی اور دن پھر بڑھا لیجیے گا۔\", \"مدد مانگنا ہمت کی بات ہے، کمزوری کی نہیں۔\", \"ایک اور کام کو نہ کہنے کا آپ کو حق ہے۔\", \"اگر آج آپ کو تنہائی محسوس ہوئی، تو ایسا محسوس کرنے والی آپ اکیلی ماں نہیں ہیں۔ ہم بہت سی ہیں۔\", \"آپ ایسی سہیلی کی حقدار ہیں جو آپ کا حال پوچھے اور جواب کا انتظار کرے۔\", \"پہلے خود بات شروع کرنا ٹھیک ہے۔ زیادہ تر مائیں یہی چاہتی ہیں کہ کوئی پہل کرے۔\", \"نظرانداز محسوس کرنے کا مطلب یہ نہیں کہ آپ اہم نہیں۔ آپ بہت اہم ہیں۔\", \"آپ کے جذبات سمجھ میں آتے ہیں۔ آپ ضرورت سے زیادہ نہیں ہیں۔\", \"یہاں آپ کو اپنا مشکل دن سمجھانے کی ضرورت نہیں۔ ہم سمجھتے ہیں۔\", \"کسی دوسری ماں کو \\\"میرے ساتھ بھی\\\" لکھا ایک میسج پورا دن بدل سکتا ہے۔\", \"دودھ پلانا، کپڑے بدلنا، جھلانا، اور پھر وہی۔ یہ اصل کام ہے، چاہے بس بیٹھے رہنے جیسا لگے۔\", \"آپ اور آپ کا بچہ ابھی ایک دوسرے کو جان رہے ہیں۔ کوئی جلدی نہیں۔\", \"نومولود کے ساتھ دن لمبے ہوتے ہیں۔ یہ دور ہمیشہ نہیں رہے گا۔\", \"اگر آج آپ نے بس ایک ننھی سی جان کا پیٹ بھرا اور اسے گرم رکھا، تو آپ نے بہت بڑا کام کیا۔\", \"آپ کو جلدی پہلے جیسا ہونے کی ضرورت نہیں۔ آپ جہاں ہیں، وہیں رہ سکتی ہیں۔\", \"بچے کو جیسے بھی دودھ ملے، آپ اس کا خیال رکھ رہی ہیں۔ یہی اصل بات ہے۔\", \"نیند کم اور پیار بھرپور، دونوں ایک ساتھ ہو سکتے ہیں۔\", \"بچے کو گود میں لیں اور گھر کے کام چھوڑ دیں۔ گھر کہیں نہیں جا رہا۔\", \"دکان میں بچے کا مچلنا آپ کو بری ماں نہیں بناتا۔ اس کا مطلب بس یہ ہے کہ آپ کا بچہ چھوٹا ہے۔\", \"چھوٹے بچے حدیں اس لیے آزماتے ہیں کیونکہ آپ کے ساتھ وہ محفوظ محسوس کرتے ہیں۔\", \"آج آپ کل سے ایک منٹ زیادہ پرسکون رہیں۔ یہ گنا جاتا ہے۔\", \"اگر غصہ آ گیا، تو ایک جپھی اور ایک \\\"معاف کرنا\\\" بہت کچھ ٹھیک کر دیتے ہیں۔ اور اس سے بچے کچھ اچھا بھی سیکھتے ہیں۔\", \"چپچپے ہاتھ، اونچی آوازیں، بڑے جذبات۔ آپ ایک پورا انسان پروان چڑھا رہی ہیں۔\", \"اس گھنٹے کا پانچواں \\\"کیوں؟\\\" ایک ننھا ذہن ہے جو بڑھ رہا ہے۔\", \"خوشگوار یاد بنانے کے لیے مکمل دن کی ضرورت نہیں۔\", \"زور سے بند ہوا دروازہ کہانی کا اختتام نہیں۔ روشنی جلائے رکھیں۔\", \"آپ کا نوعمر بچہ شاید کہے نہیں، مگر آپ کا ہر دن ساتھ ہونا اس کے لیے معنی رکھتا ہے۔\", \"گھر میں پرسکون رہنے والی بننا محنت کا کام ہے۔ اور آپ یہ کر رہی ہیں۔\", \"کچھ بہترین باتیں گاڑی میں ہوتی ہیں۔ بس چلتی رہیں۔\", \"وہ بڑے ہونے کے لیے دور جاتے ہیں، آپ کو پیچھے چھوڑنے کے لیے نہیں۔\", \"آپ کو ہر سوال کا جواب معلوم ہونا ضروری نہیں۔ سننا ہی بہت بڑی بات ہے۔\", \"بڑے بچوں کو اب بھی آپ کی ضرورت ہے، بس خاموش طریقوں سے۔\", \"سب کچھ اکیلے سنبھالنے میں ایسی طاقت لگتی ہے جو زیادہ تر لوگ کبھی نہیں دیکھ پاتے۔\", \"آپ اپنے بچے کے لیے کافی اچھی ماں ہیں۔ ہمیشہ سے تھیں۔\", \"دو ہاتھ، سو کام۔ خود پر تھوڑی نرمی کریں۔\", \"آپ کے بچے آپ کو دیکھ کر سیکھ رہے ہیں کہ ایک مضبوط اور محبت کرنے والا انسان کیسا ہوتا ہے۔\", \"تھوڑا رکنا ذمہ داری چھوڑنا نہیں۔ اسی سے آپ آگے چل پاتی ہیں۔\", \"کوئی حساب نہیں رکھ رہا۔ محبت اور ساتھ ہونا، یہی اصل بات ہے۔\", \"غم اور محبت ایک ہی جگہ سے آتے ہیں۔ کسی کی یاد آنا بتاتا ہے کہ آپ نے کتنی محبت کی۔\", \"غم کا کوئی صحیح وقت مقرر نہیں ہوتا۔ جتنا وقت چاہیے، اتنا لیں۔\", \"مشکل برسیوں پر خود کے ساتھ اتنی ہی نرمی رکھیں جتنی کسی سہیلی کے ساتھ رکھتیں۔\", \"آپ اداسی لیے ہوئے بھی اپنے بچوں کے ساتھ ہنس سکتی ہیں۔ دونوں سچ ہیں۔\", \"اگر آپ نے حمل یا بچہ کھویا ہے، تو وہ دکھ سچا ہے، اور آپ کی محبت بھی۔\", \"کچھ دن غم خاموش رہتا ہے اور کچھ دن شور مچاتا ہے۔ دونوں ٹھیک ہیں۔\", \"پیسوں کی کمی کا مطلب محبت کی کمی نہیں۔\", \"آپ کے بچوں کو خریدی ہوئی چیزوں سے زیادہ آپ کے ساتھ گزارا وقت یاد رہے گا۔\", \"بلوں کے لیے مدد کے بارے میں پوچھنا سمجھداری ہے، شرم کی بات نہیں۔ مدد اسی لیے تو ہے۔\", \"پارک میں بغیر پیسوں کی ایک دوپہر ہفتے کا بہترین دن بن سکتی ہے۔\", \"آپ نے پیسوں کو ایک ہفتہ اور کھینچ لیا۔ یہ واقعی ہنر ہے۔\", \"پیسوں کی فکر تھکا دیتی ہے۔ آپ بہت کچھ اٹھائے ہوئے ہیں، اور پھر بھی ڈٹی ہوئی ہیں۔\", \"آج آپ نے ایک گلاس پانی پیا۔ وہیں سے شروع کریں۔\", \"سب گھر سے نکل گئے۔ شاید جوتے میل نہیں کھا رہے تھے۔ پھر بھی جیت ہے۔\", \"آپ نے وہ فون کر ہی دیا جس سے آپ گھبرا رہی تھیں۔ یہ ہمت تھی۔\", \"آج آپ ہنسیں۔ اسے سنبھال کر رکھیں۔\", \"گرم کھانا، صاف کپڑے، سوتے وقت کی کہانی۔ چھوٹی چھوٹی باتیں مل کر بچپن بناتی ہیں۔\", \"آج آپ نے کسی کے ساتھ اچھا سلوک کیا، چاہے وہ آپ خود ہی کیوں نہ ہوں۔\", \"مکمل ہونا نہیں، آگے بڑھنا۔ آج آپ آگے بڑھیں۔\", \"آپ نے فہرست کا ایک کام پورا کیا۔ کچھ نہ ہونے سے ایک زیادہ۔\", \"آپ اچھی ماں ہیں۔ آپ کو اس کی فکر ہے، یہی بتاتا ہے کہ آپ کو کتنی پروا ہے۔\", \"دن بھر میں جتنا کر پاتی ہیں، آپ اس سے کہیں بڑھ کر ہیں۔\", \"آپ کے بچوں کو مکمل ماں نہیں چاہیے۔ انہیں آپ چاہییں، اور آپ ان کے پاس ہیں۔\", \"خود کے ساتھ اتنا ہی صبر رکھیں جتنا اپنے بچوں کے ساتھ رکھتی ہیں۔\", \"آپ کو اپنی جگہ لینے، چیزیں چاہنے اور اپنے خواب رکھنے کا حق ہے۔\", \"ایک غلطی محبت کو مٹا نہیں دیتی۔ کل نئی شروعات ہے۔\", \"آپ کسی کی پوری دنیا ہیں، اور آپ اپنی ذات میں بھی ایک انسان ہیں۔\", \"ہر لمحہ اچھا نہ لگنا ٹھیک ہے۔ آپ پھر بھی اپنے بچوں سے پورے دل سے محبت کر سکتی ہیں۔\", \"ماں بننے کا کوئی ایک صحیح طریقہ نہیں۔ آپ کا طریقہ بھی ٹھیک ہے۔\", \"درخت والے آسن کی طرح ڈگمگانا ٹھیک ہے۔ آپ پھر سے توازن پا سکتی ہیں۔\", \"پہاڑ والے آسن کی طرح پاؤں جما لیں۔ آپ جتنا محسوس کرتی ہیں، اس سے زیادہ مضبوطی سے کھڑی ہیں۔\", \"جنگجو دو: مضبوط ٹانگیں، کھلے بازو۔ یہی آپ ہیں، اس ہفتے کا سامنا کرتی ہوئی۔\", \"چار گن کر سانس لیں، چار گن کر چھوڑیں۔ آپ یہیں ہیں، اور اچھا کر رہی ہیں۔\", \"ستارے کی طرح کھل کر پھیلیں۔ آپ کو جگہ لینے کا حق ہے۔\", \"چوڑی، نیچی بیٹھک میں ٹکے رہنا مشکل ہے۔ لمبا دن بھی ایسا ہی ہے۔ اور آپ ٹکی ہوئی ہیں۔\", \"آپ ہلال کی طرح جھک کر بھی کھڑی رہ سکتی ہیں۔\", \"ابھی پاؤں کی انگلیاں چھونا ضروری نہیں۔ ہر تھوڑا سا کھنچاؤ بھی گنا جاتا ہے۔\", \"تکون والا آسن: ایک ہاتھ نیچے، ایک ہاتھ اوپر۔ زمین سے جڑی رہیں اور کھنچتی رہیں۔\", \"دیر ہو گئی ہے۔ جو آج نہیں ہوا، وہ کل تک رک سکتا ہے۔\", \"اس وقت بچے کے ساتھ جاگ رہی ہیں؟ اس لمحے بہت سی مائیں آپ کے ساتھ جاگ رہی ہیں۔\", \"گھر خاموش ہے۔ یہ لمحہ آپ کا ہے۔ سانس لیں۔\", \"آپ نے آج کا دن پار کر لیا۔ آج کو بس اتنا ہی چاہیے تھا۔\", \"اگر آج رات دماغ بےچین ہے، تو سب لکھ لیں اور اسے صبح تک رکنے دیں۔\", \"آنکھوں کو آرام دیں۔ کل پھر سے شروع کر سکتی ہیں۔\", \"تہوار خوشی کے ساتھ ساتھ مشکل بھی ہو سکتے ہیں۔ یہ موسم آپ کو جیسا بھی لگے، ٹھیک ہے۔\", \"دسترخوان کا مکمل ہونا ضروری نہیں۔ اس کے اردگرد بیٹھے لوگ ہی اصل بات ہیں۔\", \"اگر اس سال کسی کی کمی محسوس ہو رہی ہے، تو اپنے دل کے ساتھ نرمی کریں۔\", \"شکریہ امی، ہر کھانے، ہر سفر اور ہر جپھی کے لیے۔\", \"مہمان بلانا، پکوان بنانا یا ہر وقت مسکرانا ضروری نہیں۔ سادہ تہوار بھی تہوار ہی ہے۔\", \"اس سال آپ کے بچوں کو ملنے والا سب سے اچھا تحفہ آپ کے ساتھ گزارا وقت ہے۔\", \"چھوٹا سا جشن بھی محبت سے بھرا ہوتا ہے۔ اسے خاص بنانے کے لیے زیادہ پیسے نہیں چاہییں۔\", \"ٹھنڈے دن، گرم جپھیاں۔ آپ اپنے گھر کی گرمی ہیں۔\", \"تہواروں کی کچھ بھاگ دوڑ چھوڑ دینا ٹھیک ہے۔ سکون بھی ایک تحفہ ہے۔\", \"اگر اس سال یہ موسم بھاری لگ رہا ہے، تو آپ اکیلی نہیں ہیں۔ ایک ایک دن کر کے چلیں۔\"]";D.body.appendChild(e)})();
